import { describe, it, expect } from "vitest";
import {
  coerceClassifyConfig, appTypeOf, lifecycleOf, appTypeHasUi, classifySignals,
  uiSystemOf, rendersFromStudio, algorithmSystemOf, computesFromStudio, hostRunsProjectArtifacts,
  APP_TYPES, LIFECYCLES, SYSTEM_SOURCES,
} from "@/features/planner/lib/classifyConfig";

describe("coerceClassifyConfig", () => {
  it("drops a mistyped or unknown field rather than failing the whole blob", () => {
    const cfg = coerceClassifyConfig({
      uiMode: "custom", appType: "not-a-type", lifecycle: 7, needsSource: "yes", needsMcp: true,
    });
    expect(cfg).toEqual({ uiMode: "custom", needsMcp: true });
  });

  it("reads the two taxonomy axes when they carry valid tokens", () => {
    expect(coerceClassifyConfig({ appType: "mcp-server", lifecycle: "transform" }))
      .toEqual({ appType: "mcp-server", lifecycle: "transform" });
  });

  it("accepts every token in each published taxonomy", () => {
    for (const t of APP_TYPES) expect(coerceClassifyConfig({ appType: t })).toEqual({ appType: t });
    for (const l of LIFECYCLES) expect(coerceClassifyConfig({ lifecycle: l })).toEqual({ lifecycle: l });
    for (const s of SYSTEM_SOURCES) expect(coerceClassifyConfig({ uiSystem: s })).toEqual({ uiSystem: s });
  });

  it("keeps uiSystem and uiMode as independent axes (#4115)", () => {
    // The trap the axis exists to close: `external` is NOT "the project owns rendering" — it still
    // means our pipeline renders a shell from files the user supplies. All four combinations are real.
    expect(coerceClassifyConfig({ uiSystem: "own", uiMode: "external" }))
      .toEqual({ uiSystem: "own", uiMode: "external" });
    expect(coerceClassifyConfig({ uiSystem: "own", uiMode: "custom" }))
      .toEqual({ uiSystem: "own", uiMode: "custom" });
    // An unknown token is dropped, not coerced to a neighbour — a typo must not silently opt a
    // project INTO a UI system it doesn't use.
    expect(coerceClassifyConfig({ uiSystem: "owned" })).toEqual({});
    expect(coerceClassifyConfig({ uiSystem: "external" })).toEqual({});
  });

  it("reads the two SYSTEM axes independently (#4115)", () => {
    // They differ often — owning the UI while still drawing algorithms from the graph is a normal
    // project, and it is exactly the case a single combined answer would get wrong.
    expect(coerceClassifyConfig({ uiSystem: "own", algorithmSystem: "studio" }))
      .toEqual({ uiSystem: "own", algorithmSystem: "studio" });
    expect(coerceClassifyConfig({ uiSystem: "studio", algorithmSystem: "own" }))
      .toEqual({ uiSystem: "studio", algorithmSystem: "own" });
    for (const s of SYSTEM_SOURCES) {
      expect(coerceClassifyConfig({ algorithmSystem: s })).toEqual({ algorithmSystem: s });
    }
    // Same discipline as its twin: a bad token is dropped, never coerced.
    expect(coerceClassifyConfig({ algorithmSystem: "graph" })).toEqual({});
  });

  it("reads a non-object as null and an empty object as an empty config", () => {
    expect(coerceClassifyConfig(null)).toBeNull();
    expect(coerceClassifyConfig("custom")).toBeNull();
    expect(coerceClassifyConfig({})).toEqual({});
  });
});

describe("the unclassified defaults", () => {
  // The load-bearing invariant (#3784): classification must never hide a stage that showed before
  // the planner classified, so every default reads as the permissive value.
  it("reads an unclassified project as a greenfield application WITH a UI", () => {
    for (const cfg of [undefined, null, {}]) {
      expect(appTypeOf(cfg)).toBe("application");
      expect(lifecycleOf(cfg)).toBe("greenfield");
      expect(appTypeHasUi(cfg)).toBe(true);
    }
  });

  it("reads an unclassified project as studio-rendered — the axis is non-regressing (#4115)", () => {
    // Every project that exists today renders from our system, so unset MUST read as "studio":
    // that is what makes the axis additive with no migration and no backfill.
    for (const cfg of [undefined, null, {}]) {
      expect(uiSystemOf(cfg)).toBe("studio");
      expect(rendersFromStudio(cfg)).toBe(true);
    }
    // …and an explicit `own` is the only thing that turns our pipeline off.
    expect(rendersFromStudio({ uiSystem: "own" })).toBe(false);
    expect(uiSystemOf({ uiSystem: "own" })).toBe("own");
    // uiMode alone never opts a project out — the whole point of the separate axis.
    expect(rendersFromStudio({ uiMode: "external" })).toBe(true);
  });

  it("reads an unclassified project as studio for BOTH systems", () => {
    for (const cfg of [undefined, null, {}]) {
      expect(algorithmSystemOf(cfg)).toBe("studio");
      expect(computesFromStudio(cfg)).toBe(true);
      expect(hostRunsProjectArtifacts(cfg)).toBe(true);
    }
    expect(computesFromStudio({ algorithmSystem: "own" })).toBe(false);
  });
});

describe("hostRunsProjectArtifacts — the isolate-before-render question (#4115)", () => {
  // `studio` means our HOST takes the project's LLM-authored code in and runs it: UI rendered in a
  // frame (opaque-origin in ComponentPreviewFrame; #3862 is the frame that still isn't), algorithms
  // compiled with `new Function` and executed in the vizCode worker (#3233). So this must be an OR —
  // isolation is owed if ANY one surface hosts project code.
  it("is true when EITHER system is studio, not only when the UI is", () => {
    expect(hostRunsProjectArtifacts({ uiSystem: "own", algorithmSystem: "studio" })).toBe(true);
    expect(hostRunsProjectArtifacts({ uiSystem: "studio", algorithmSystem: "own" })).toBe(true);
    expect(hostRunsProjectArtifacts({ uiSystem: "studio", algorithmSystem: "studio" })).toBe(true);
  });

  it("is false only when the project owns BOTH halves", () => {
    expect(hostRunsProjectArtifacts({ uiSystem: "own", algorithmSystem: "own" })).toBe(false);
  });

  it("would answer wrongly if it read only the UI axis — the regression this guards", () => {
    // The project that owns its UI but draws algorithms from the graph: reading `uiSystem` alone says
    // "we host nothing", while its vizCode still executes here. That is the drop this predicate exists
    // to prevent, and it's the more dangerous half — it runs code rather than rendering it.
    const ownUiStudioAlgorithms = { uiSystem: "own", algorithmSystem: "studio" } as const;
    expect(rendersFromStudio(ownUiStudioAlgorithms)).toBe(false);
    expect(hostRunsProjectArtifacts(ownUiStudioAlgorithms)).toBe(true);
  });
});

describe("appTypeHasUi", () => {
  it("is true exactly for the app types that have screens", () => {
    const withUi = APP_TYPES.filter((t) => appTypeHasUi({ appType: t }));
    expect(withUi.sort()).toEqual(["application", "desktop", "mobile", "static"]);
  });

  it("is false for the headless types, so their UI stage drops", () => {
    for (const t of ["api", "serverless", "cli", "library", "mcp-server"] as const) {
      expect(appTypeHasUi({ appType: t })).toBe(false);
    }
  });
});

describe("classifySignals", () => {
  it("publishes exactly one true signal per axis", () => {
    const sig = classifySignals({ appType: "api", lifecycle: "harden" });
    expect(sig["appType:api"]).toBe(true);
    expect(sig["appType:application"]).toBe(false);
    expect(sig["lifecycle:harden"]).toBe(true);
    expect(sig["lifecycle:greenfield"]).toBe(false);
    expect(APP_TYPES.filter((t) => sig[`appType:${t}`])).toEqual(["api"]);
    expect(LIFECYCLES.filter((l) => sig[`lifecycle:${l}`])).toEqual(["harden"]);
  });

  it("carries hasUserInterface so a stage's appliesWhen can key on it", () => {
    expect(classifySignals({ appType: "mcp-server" }).hasUserInterface).toBe(false);
    expect(classifySignals({ appType: "mobile" }).hasUserInterface).toBe(true);
  });

  it("emits the default axes for an unclassified project", () => {
    const sig = classifySignals(undefined);
    expect(sig["appType:application"]).toBe(true);
    expect(sig["lifecycle:greenfield"]).toBe(true);
    expect(sig["uiSystem:studio"]).toBe(true);
    expect(sig["algorithmSystem:studio"]).toBe(true);
    expect(sig.hasUserInterface).toBe(true);
    expect(sig.rendersFromStudio).toBe(true);
    expect(sig.computesFromStudio).toBe(true);
  });

  it("carries rendersFromStudio so a studio-only stage can drop for an `own` project (#4115)", () => {
    expect(classifySignals({ uiSystem: "own" }).rendersFromStudio).toBe(false);
    expect(classifySignals({ uiSystem: "own" })["uiSystem:own"]).toBe(true);
    expect(classifySignals({ uiSystem: "own" })["uiSystem:studio"]).toBe(false);
    // Independent of the screens question — an `own` project can still very much have a UI.
    expect(classifySignals({ uiSystem: "own", appType: "application" }).hasUserInterface).toBe(true);
  });

  it("carries the algorithm axis and the combined host signal too (#4115)", () => {
    const sig = classifySignals({ uiSystem: "own", algorithmSystem: "studio" });
    expect(sig.computesFromStudio).toBe(true);
    expect(sig["algorithmSystem:studio"]).toBe(true);
    expect(sig["algorithmSystem:own"]).toBe(false);
    // The two axes are independent signals, and the combined one is an OR over both.
    expect(sig.rendersFromStudio).toBe(false);
    expect(sig.hostRunsProjectArtifacts).toBe(true);
    expect(classifySignals({ uiSystem: "own", algorithmSystem: "own" }).hostRunsProjectArtifacts).toBe(false);
  });

  it("emits a boolean for every token, so an absent signal is never ambiguous", () => {
    const sig = classifySignals({ appType: "cli" });
    for (const t of APP_TYPES) expect(typeof sig[`appType:${t}`]).toBe("boolean");
    for (const l of LIFECYCLES) expect(typeof sig[`lifecycle:${l}`]).toBe("boolean");
    for (const s of SYSTEM_SOURCES) expect(typeof sig[`uiSystem:${s}`]).toBe("boolean");
    for (const s of SYSTEM_SOURCES) expect(typeof sig[`algorithmSystem:${s}`]).toBe("boolean");
  });
});

// The classification TAXONOMY, captured from the live TypeScript so Rust can be held to it.
//
// ## This is not a port — both copies already exist
//
// `APP_TYPES`, `LIFECYCLES` and `SYSTEM_SOURCES` are declared twice: here, and as `pub const` arrays
// in the record `plandb--validate.rs` (plandb compiles from the graph — there is no
// `crates/plandb/src/validate.rs` file), where `validate_classify_config` REJECTS any value outside
// them. So the Rust copy is a GATE, not documentation. They are byte-identical today and nothing
// checks that they stay so.
//
// The failure is silent and asymmetric, which is why it is worth a fixture rather than a comment:
// the app offers an `appType` the CLI refuses, or the planner writes a `lifecycle` the app cannot
// read, and the first symptom is a rejected `bsc plan classify` write nobody expected — or an
// accepted one the app then renders as unknown. Same shape as the two hand-copied gate tables behind
// `a-directors-pane-can-never-write-the-gate-that-lets-it-launch`, where the tables agreed until they
// did not and a director could never launch.
//
//     UPDATE_FIXTURES=1 npx vitest run .bsc-records/features/planner/lib/classifyConfig.1.test.ts
//
// ## Both drift directions are covered, which is the point
//
//   * a token added to the TYPESCRIPT  → this test goes red, because the committed fixture is stale;
//   * a token added to RUST            → the Rust test goes red, because the fixture does not have it;
//   * a regeneration after a TS change → the Rust test goes red until Rust is brought level.
//
// So neither side can move alone. Nothing is re-homed: the constants stay exactly where they are.
//
// ## Named after the CONCERN, not the module — deliberately
//
// The convention is one fixture per module. `classify-config.ts` carries three separable concerns
// (this vocabulary, a `coerce` that overlaps but does not equal the Rust validator, and derived
// predicates that exist only here), and `triage-the-planner-records-before-any-of-them-is-ported`
// found that the concern — not the record — is the unit of work in this lane. So this file is named
// for the vocabulary, leaving `classifyPredicates.fixtures.json` free for the item that follows.
//
// ## One vocabulary is deliberately ABSENT, and that is recorded rather than hidden
//
// `uiMode` (`"custom" | "external"`) is duplicated the same way — as a TYPE union here and as an
// inline `matches!` in `validate_classify_config`. A type union erases at runtime, so a fixture
// generated from live code CANNOT capture it; writing it by hand would be the very thing this file
// exists to avoid. Binding it needs a `UI_MODES` const exported first. See the change record.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { APP_TYPES, LIFECYCLES, SYSTEM_SOURCES } from "@/features/planner/lib/classifyConfig";

const FIXTURE = join(process.cwd(), "src/features/planner/lib/classifyTaxonomy.fixtures.json");

function build() {
  return {
    note: "GENERATED from the live TypeScript — see classifyTaxonomy.fixtures.gen.test.ts",
    // ORDER IS PART OF THE CONTRACT, not incidental: `validate_classify_config` renders the list back
    // to the planner verbatim in its rejection message ("must be one of: …"), so a reordering changes
    // what an agent is told to correct itself with.
    appTypes: [...APP_TYPES],
    lifecycles: [...LIFECYCLES],
    systemSources: [...SYSTEM_SOURCES],
  };
}

describe("the classification taxonomy is captured so both sides are held to it", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const built = build();
    const text = JSON.stringify(built, null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  /** The committed fixture is what Rust reads, so it must be non-empty and the right size. */
  it("carries every axis at its known arity", () => {
    const fx = JSON.parse(readFileSync(FIXTURE, "utf8"));
    expect(fx.appTypes).toHaveLength(9);
    expect(fx.lifecycles).toHaveLength(5);
    expect(fx.systemSources).toHaveLength(2);
    for (const k of ["appTypes", "lifecycles", "systemSources"]) {
      expect(new Set(fx[k]).size, `${k} must have no duplicates`).toBe(fx[k].length);
      for (const t of fx[k]) expect(typeof t, `${k} tokens are strings`).toBe("string");
    }
  });
});

// The classification's DERIVED PREDICATES, captured from the live TypeScript so Rust can match them.
//
// ## Why these move and the vocabulary did not
//
// `crates/plandb` STORES a classification (`classify_set`/`classify_get`) and VALIDATES it
// (`validate_classify_config`). It never asks anything OF it. Every question about what a
// classification MEANS is answered in the renderer — and those answers drive real behaviour: which
// stages a project needs, whether the designer is wired in, whether the host must isolate before it
// renders, what the director is told. A worker or director asking the same question today cannot:
// `bsc plan classify get` returns the blob, but its meaning is not reachable, so a session must
// re-derive the rules from prose.
//
//     UPDATE_FIXTURES=1 npx vitest run .bsc-records/features/planner/lib/classifyConfig.2.test.ts
//
// ## The defaulting is the subtle part, so it is the part the corpus is built around
//
// Every accessor takes `ClassifyConfig | undefined | null` and returns a DEFAULT, so "absent" and
// "explicitly set to the default" are indistinguishable downstream. That is a decision, it is written
// down nowhere in Rust, and a port returning an Option instead would change behaviour at every call
// site. Each accessor therefore gets all three input states: a config that sets the field, a config
// that omits it, and no config at all — with `null` and `undefined` both present, because they are
// two ways of saying nothing and must stay indistinguishable.
//
// `usesGithub` is the deliberate EXCEPTION and is pinned as one: it has no accessor and no default,
// because unset means UNDECIDED and defaulting it to `false` would look settled. `bsc publish`
// refuses only on an explicit `false`. A port that gave it a default would silently decide something
// nobody answered.
//
// ## Why every token, not a sample
//
// `appTypeHasUi` branches on a private `UI_BEARING` subset (application · desktop · mobile · static)
// and `classifySignals` emits one boolean PER token across four axes. A sampled corpus would leave
// most of both unexercised, so the generator walks the full taxonomy — which is safe to do now that
// `classifyTaxonomy.fixtures.json` proves the two copies of that taxonomy agree.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  APP_TYPES, LIFECYCLES, SYSTEM_SOURCES,
  appTypeOf, lifecycleOf, uiSystemOf, algorithmSystemOf,
  rendersFromStudio, computesFromStudio, hostRunsProjectArtifacts, appTypeHasUi, classifySignals,
  type ClassifyConfig,
} from "@/features/planner/lib/classifyConfig";

const FIXTURE = join(process.cwd(), "src/features/planner/lib/classifyPredicates.fixtures.json");

/** How the input is carried, so `null` and `undefined` stay distinguishable in JSON. */
type Input = { kind: "null" } | { kind: "undefined" } | { kind: "config"; value: ClassifyConfig };

const CASES: { name: string; input: Input }[] = [
  // ── nothing at all: the two ways of saying it must agree ────────────────────────────────────
  { name: "no config — null", input: { kind: "null" } },
  { name: "no config — undefined", input: { kind: "undefined" } },
  { name: "an EMPTY config is not the same input as no config, but must read the same", input: { kind: "config", value: {} } },

  // ── every appType, because appTypeHasUi branches on a subset of them ────────────────────────
  ...APP_TYPES.map((t) => ({ name: `appType=${t}`, input: { kind: "config", value: { appType: t } } as Input })),

  // ── every lifecycle, because classifySignals emits one boolean per token ────────────────────
  ...LIFECYCLES.map((l) => ({ name: `lifecycle=${l}`, input: { kind: "config", value: { lifecycle: l } } as Input })),

  // ── the FOUR system combinations. hostRunsProjectArtifacts is an OR, and own/own is the only
  //    input that makes it false — a port reading only uiSystem answers it wrongly for studio
  //    algorithms under an own UI, which is the more dangerous half since it RUNS code.
  ...SYSTEM_SOURCES.flatMap((ui) =>
    SYSTEM_SOURCES.map((algo) => ({
      name: `uiSystem=${ui} algorithmSystem=${algo}`,
      input: { kind: "config", value: { uiSystem: ui, algorithmSystem: algo } } as Input,
    })),
  ),

  // ── a fully-populated config, and one where every needs* flag is set, so the signal bag is
  //    exercised with real neighbours rather than in isolation.
  {
    name: "a fully classified project",
    input: {
      kind: "config",
      value: {
        uiMode: "custom", appType: "mobile", lifecycle: "harden",
        uiSystem: "own", algorithmSystem: "studio", usesGithub: true,
        needsMarket: true, needsSource: false, needsMcp: true, needsSkills: false, needsAutomations: true,
      },
    },
  },
  {
    name: "usesGithub explicitly FALSE — the one axis with no default",
    input: { kind: "config", value: { usesGithub: false } },
  },
  {
    name: "usesGithub UNSET — undecided, and must not read as false anywhere",
    input: { kind: "config", value: { appType: "api" } },
  },
];

const resolve = (i: Input): ClassifyConfig | null | undefined =>
  i.kind === "null" ? null : i.kind === "undefined" ? undefined : i.value;

function build() {
  return {
    note: "GENERATED from the live TypeScript — see classifyPredicates.fixtures.gen.test.ts",
    uiBearing: APP_TYPES.filter((t) => appTypeHasUi({ appType: t })),
    cases: CASES.map(({ name, input }) => {
      const cfg = resolve(input);
      return {
        name,
        input,
        appType: appTypeOf(cfg),
        lifecycle: lifecycleOf(cfg),
        uiSystem: uiSystemOf(cfg),
        algorithmSystem: algorithmSystemOf(cfg),
        rendersFromStudio: rendersFromStudio(cfg),
        computesFromStudio: computesFromStudio(cfg),
        hostRunsProjectArtifacts: hostRunsProjectArtifacts(cfg),
        appTypeHasUi: appTypeHasUi(cfg),
        signals: classifySignals(cfg),
        // Carried so the port cannot quietly invent a default for the one axis that has none.
        usesGithub: cfg?.usesGithub ?? null,
      };
    }),
  };
}

describe("the classification's derived predicates are captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const built = build();
    const text = JSON.stringify(built, null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("walks the WHOLE taxonomy, not a sample", () => {
    const built = build();
    const seen = new Set(built.cases.map((c) => c.appType));
    expect(seen.size, "every appType must appear").toBe(APP_TYPES.length);
    const lifes = new Set(built.cases.map((c) => c.lifecycle));
    expect(lifes.size, "every lifecycle must appear").toBe(LIFECYCLES.length);
  });

  /** null and undefined are two ways of saying nothing and must be indistinguishable. */
  it("reads null, undefined and an empty config identically", () => {
    const built = build();
    const [a, b, c] = built.cases;
    const strip = (x: (typeof built.cases)[number]) => ({ ...x, name: "", input: null });
    expect(strip(b)).toEqual(strip(a));
    expect(strip(c)).toEqual(strip(a));
  });

  /** The OR must be reachable in every combination, or a port reading one axis passes. */
  it("exercises all four system combinations, including the only false one", () => {
    const built = build();
    const combos = built.cases.filter((c) => c.name.startsWith("uiSystem="));
    expect(combos).toHaveLength(4);
    expect(combos.filter((c) => !c.hostRunsProjectArtifacts).map((c) => c.name)).toEqual([
      "uiSystem=own algorithmSystem=own",
    ]);
  });

  /** usesGithub has no default anywhere — absent must stay absent. */
  it("never defaults usesGithub", () => {
    const built = build();
    const unset = built.cases.find((c) => c.name.startsWith("usesGithub UNSET"))!;
    expect(unset.usesGithub).toBeNull();
    const no = built.cases.find((c) => c.name.startsWith("usesGithub explicitly FALSE"))!;
    expect(no.usesGithub).toBe(false);
    for (const c of built.cases) expect(c.signals).not.toHaveProperty("usesGithub");
  });
});
